//! Synthetic stream-fit outputs for the fail-closed Q4 checkpoint loader.
//! Fixture metric values are computed on generated bytes, not measurements.
use sml_core::{
    byte_factorization::ByteFactorization,
    elastic_ngram_paged_sha::{hex, sha256},
    q4_checkpoint::{
        CheckpointSchema, Q4Checkpoint, CONTINUE_METRICS_SUFFIX, CONTINUE_SCHEMA,
        STREAM_METRICS_HEADER, STREAM_SCHEMA,
    },
    sparse_gradient_atlas::{QuantizedSparseAtlas, SparseConfig, SparseGradientAtlas},
};
use std::{
    fs,
    path::{Path, PathBuf},
    sync::atomic::{AtomicU64, Ordering},
    time::{SystemTime, UNIX_EPOCH},
};

static SERIAL: AtomicU64 = AtomicU64::new(0);

const CONFIG: SparseConfig = SparseConfig {
    pages: 8,
    max_cached_pages: 2,
    learning_rate: 0.15,
};

fn bytes(seed: u32, len: usize) -> Vec<u8> {
    let alphabet = b"abc def ghij klm. ";
    let mut state = seed.wrapping_mul(2_654_435_761).wrapping_add(7);
    (0..len)
        .map(|_| {
            state = state.wrapping_mul(1_103_515_245).wrapping_add(12_345);
            alphabet[(state >> 16) as usize % alphabet.len()]
        })
        .collect()
}

fn sha_file(path: &Path) -> String {
    hex(&sha256(&fs::read(path).unwrap()))
}

struct Fixture {
    home: PathBuf,
    out: PathBuf,
}

impl Drop for Fixture {
    fn drop(&mut self) {
        fs::remove_dir_all(&self.home).ok();
    }
}

/// Writes a stream-fit-shaped output directory: snapshot, Q4, metrics, COMPLETE.
fn stream_output(factorization: ByteFactorization, schema: CheckpointSchema) -> Fixture {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    let home = std::env::temp_dir().join(format!(
        "sml-q4-checkpoint-{}-{nanos}-{}",
        std::process::id(),
        SERIAL.fetch_add(1, Ordering::Relaxed)
    ));
    fs::create_dir_all(&home).unwrap();
    let out = home.join("model");
    let mut atlas =
        SparseGradientAtlas::create_with_factorization(&out, CONFIG, factorization).unwrap();
    for seed in 0..3 {
        atlas
            .train_document_grouped(&bytes(seed, 400), 4096)
            .unwrap();
    }
    atlas.checkpoint(&out).unwrap();
    let dev = bytes(99, 200);
    let (f32_loss, events) = atlas.evaluate_document_grouped(&dev, 4096).unwrap();
    let q4 = out.join("weights.q4");
    atlas.export_q4(&q4).unwrap();
    let mut quantized =
        QuantizedSparseAtlas::open_with_factorization(&q4, CONFIG, factorization).unwrap();
    let (q4_loss, _) = quantized.evaluate_document_grouped(&dev, 4096).unwrap();
    let counters = atlas.counters();
    let (f32_bpc, q4_bpc) = (f32_loss / events as f64, q4_loss / events as f64);
    let fact = match factorization {
        ByteFactorization::IndependentBits => "independent_bits",
        ByteFactorization::MsbTree => "msb_tree",
    };
    let mut row = format!(
        "{STREAM_SCHEMA}\t{}\t{}\t{}\t{}\t3\t1200\t1194\t1.000000000\t1\t200\t{events}\t{f32_bpc:.9}\t{q4_bpc:.9}\t{:.9}\t0.001\t1.000\t{}\t{}\t{fact}\t{}\t{}\tUNOPENED\tNOT_PROMOTED",
        "a".repeat(64),
        CONFIG.total_parameters(),
        counters.distinct_updated_parameters,
        counters.parameter_updates,
        q4_bpc - f32_bpc,
        CONFIG.train_master_bytes(),
        CONFIG.packed_q4_bytes(),
        sha_file(&q4),
        sha_file(&out.join("snapshot.tsv")),
    );
    let mut header = STREAM_METRICS_HEADER.to_string();
    if schema == CheckpointSchema::Continue {
        row = row.replacen(STREAM_SCHEMA, CONTINUE_SCHEMA, 1);
        row.push_str(&format!(
            "\t{}\t{}\t8\t9600\t10800\t1\t0",
            "b".repeat(64),
            "c".repeat(64)
        ));
        header.push_str(CONTINUE_METRICS_SUFFIX);
    }
    fs::write(out.join("metrics.tsv"), format!("{header}\n{row}\n")).unwrap();
    seal(&out, schema);
    Fixture { home, out }
}

fn seal(out: &Path, schema: CheckpointSchema) {
    fs::write(
        out.join("COMPLETE"),
        format!(
            "{}\t{}\n",
            schema.as_str(),
            sha_file(&out.join("metrics.tsv"))
        ),
    )
    .unwrap();
}

#[test]
fn valid_outputs_open_with_recorded_dimensions_on_both_factorizations() {
    for factorization in [
        ByteFactorization::IndependentBits,
        ByteFactorization::MsbTree,
    ] {
        for schema in [CheckpointSchema::Stream, CheckpointSchema::Continue] {
            let fx = stream_output(factorization, schema);
            let checkpoint = Q4Checkpoint::open_verified(&fx.out).unwrap();
            assert_eq!(checkpoint.schema, schema);
            assert_eq!(checkpoint.factorization, factorization);
            assert_eq!(checkpoint.config, CONFIG);
            assert_eq!(checkpoint.q4_sha256, sha_file(&fx.out.join("weights.q4")));
            assert_eq!(
                checkpoint.parent_q4_sha256.is_some(),
                schema == CheckpointSchema::Continue
            );
            // The opened atlas reproduces the recorded DEV Q4 value exactly.
            let mut atlas = checkpoint.open_atlas().unwrap();
            let dev = bytes(99, 200);
            let (loss, events) = atlas.evaluate_document_grouped(&dev, 4096).unwrap();
            assert_eq!(events, checkpoint.dev_events);
            assert_eq!(
                format!("{:.9}", loss / events as f64),
                checkpoint.dev_q4_bpc
            );
            let pinned =
                Q4Checkpoint::open_verified_pinned(&fx.out, &checkpoint.q4_sha256).unwrap();
            assert_eq!(pinned, checkpoint);
            assert!(Q4Checkpoint::open_verified_pinned(&fx.out, &"0".repeat(64)).is_err());
        }
    }
}

#[test]
fn missing_or_stale_complete_marker_fails_closed() {
    let fx = stream_output(ByteFactorization::MsbTree, CheckpointSchema::Stream);
    fs::remove_file(fx.out.join("COMPLETE")).unwrap();
    assert!(Q4Checkpoint::open_verified(&fx.out).is_err());
    fs::write(
        fx.out.join("COMPLETE"),
        format!("{STREAM_SCHEMA}\t{}\n", "0".repeat(64)),
    )
    .unwrap();
    assert!(Q4Checkpoint::open_verified(&fx.out).is_err());
    // Wrong schema label on a correct digest.
    seal(&fx.out, CheckpointSchema::Continue);
    assert!(Q4Checkpoint::open_verified(&fx.out).is_err());
    seal(&fx.out, CheckpointSchema::Stream);
    assert!(Q4Checkpoint::open_verified(&fx.out).is_ok());
}

#[test]
fn edited_metrics_even_if_resealed_must_still_match_artifacts() {
    let fx = stream_output(ByteFactorization::MsbTree, CheckpointSchema::Stream);
    let metrics = fs::read_to_string(fx.out.join("metrics.tsv")).unwrap();
    // Unsealed edit: COMPLETE no longer matches.
    fs::write(
        fx.out.join("metrics.tsv"),
        metrics.replace("UNOPENED", "OPENED"),
    )
    .unwrap();
    assert!(Q4Checkpoint::open_verified(&fx.out).is_err());
    // Resealed edits are rejected by the cross-checks.
    for edited in [
        metrics.replace("UNOPENED", "OPENED"),
        metrics.replace("\tmsb_tree\t", "\tindependent_bits\t"),
        metrics.replace(
            &format!("\t{}\t", CONFIG.total_parameters()),
            &format!("\t{}\t", CONFIG.total_parameters() + 1024),
        ),
        metrics.replace(&sha_file(&fx.out.join("weights.q4")), &"d".repeat(64)),
        metrics.trim_end().to_string(),
        format!("{metrics}extra\n"),
    ] {
        fs::write(fx.out.join("metrics.tsv"), &edited).unwrap();
        seal(&fx.out, CheckpointSchema::Stream);
        assert!(Q4Checkpoint::open_verified(&fx.out).is_err(), "{edited}");
    }
}

#[test]
fn corrupted_truncated_or_symlinked_q4_is_rejected() {
    let fx = stream_output(ByteFactorization::IndependentBits, CheckpointSchema::Stream);
    let q4 = fx.out.join("weights.q4");
    let original = fs::read(&q4).unwrap();
    let mut flipped = original.clone();
    flipped[17] ^= 0x10;
    fs::write(&q4, &flipped).unwrap();
    assert!(Q4Checkpoint::open_verified(&fx.out).is_err());
    fs::write(&q4, &original[..original.len() - 512]).unwrap();
    assert!(Q4Checkpoint::open_verified(&fx.out).is_err());
    fs::write(&q4, &original).unwrap();
    let checkpoint = Q4Checkpoint::open_verified(&fx.out).unwrap();
    // Mutation after verification is caught when the atlas is opened.
    fs::write(&q4, &flipped).unwrap();
    assert!(checkpoint.open_atlas().is_err());
    #[cfg(unix)]
    {
        let real = fx.home.join("real.q4");
        fs::write(&real, &original).unwrap();
        fs::remove_file(&q4).unwrap();
        std::os::unix::fs::symlink(&real, &q4).unwrap();
        assert!(Q4Checkpoint::open_verified(&fx.out).is_err());
    }
}

/// Replace snapshot.tsv, then update its digest in metrics.tsv and reseal, so
/// only the semantic cross-checks (not the digests) can reject it.
fn rewrite_snapshot_consistently(out: &Path, new_snapshot: &str) {
    let snapshot_path = out.join("snapshot.tsv");
    let old_sha = sha_file(&snapshot_path);
    fs::write(&snapshot_path, new_snapshot).unwrap();
    let metrics = fs::read_to_string(out.join("metrics.tsv")).unwrap();
    fs::write(
        out.join("metrics.tsv"),
        metrics.replace(&old_sha, &sha_file(&snapshot_path)),
    )
    .unwrap();
    seal(out, CheckpointSchema::Stream);
}

#[test]
fn snapshot_tamper_factorization_mismatch_and_partial_temporaries_fail() {
    let fx = stream_output(ByteFactorization::MsbTree, CheckpointSchema::Stream);
    let snapshot_path = fx.out.join("snapshot.tsv");
    let snapshot = fs::read_to_string(&snapshot_path).unwrap();
    // Unsealed snapshot edit: digest mismatch.
    fs::write(&snapshot_path, snapshot.replacen("\t2\t", "\t4\t", 1)).unwrap();
    assert!(Q4Checkpoint::open_verified(&fx.out).is_err());
    fs::write(&snapshot_path, &snapshot).unwrap();
    assert!(Q4Checkpoint::open_verified(&fx.out).is_ok());
    // Digest-consistent factorization flip (metrics still says msb_tree).
    rewrite_snapshot_consistently(
        &fx.out,
        &snapshot.replace("SML_SPARSE_GRADIENT_V2_MSB_TREE", "SML_SPARSE_GRADIENT_V1"),
    );
    assert!(Q4Checkpoint::open_verified(&fx.out).is_err());
    // Digest-consistent page-count change.
    rewrite_snapshot_consistently(&fx.out, &snapshot.replacen("\t8\t", "\t16\t", 1));
    assert!(Q4Checkpoint::open_verified(&fx.out).is_err());
    // Digest-consistent update-accounting change.
    let fields = snapshot.trim_end().split('\t').collect::<Vec<_>>();
    let mut altered = fields.clone();
    let bumped = (fields[6].parse::<u64>().unwrap() + 1).to_string();
    altered[6] = &bumped;
    rewrite_snapshot_consistently(&fx.out, &format!("{}\n", altered.join("\t")));
    assert!(Q4Checkpoint::open_verified(&fx.out).is_err());
    rewrite_snapshot_consistently(&fx.out, &snapshot);
    assert!(Q4Checkpoint::open_verified(&fx.out).is_ok());
    fs::write(fx.out.join("snapshot.tsv.tmp"), "partial").unwrap();
    assert!(Q4Checkpoint::open_verified(&fx.out).is_err());
    fs::remove_file(fx.out.join("snapshot.tsv.tmp")).unwrap();
    fs::remove_file(fx.out.join("metrics.tsv")).unwrap();
    assert!(Q4Checkpoint::open_verified(&fx.out).is_err());
}
